@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";
@source "../node_modules/streamdown/dist/*.js";

@custom-variant dark (&:is(.dark *));

/*
 * Design system definition.
 *
 * The @theme inline block maps CSS custom properties to Tailwind utility
 * classes (e.g. --color-primary -> bg-primary, text-primary).
 *
 * The :root and .dark blocks define the actual color values using oklch.
 * All colors MUST use oklch format.
 *
 * To add a new semantic color:
 * 1. Add the variable to :root (light value) and .dark (dark value)
 * 2. Register it in @theme inline as --color-<name>: var(--<name>)
 */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-glass: var(--glass);
  --color-glass-hover: var(--glass-hover);
  --color-glass-border: var(--glass-border);
  --color-glass-highlight: var(--glass-highlight);
  --color-brand-blue: var(--brand-blue);
  --color-brand-indigo: var(--brand-indigo);
  --color-brand-violet: var(--brand-violet);
  --font-sans: "DM Sans", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Space Grotesk", "DM Sans", ui-sans-serif, system-ui, sans-serif;
  --animate-fade-in: fade-in 0.35s ease-out both;
  --animate-message-in: message-in 0.3s ease-out both;
}

:root {
  --radius: 0.625rem;
  --background: oklch(0.965 0.008 260);
  --foreground: oklch(0.18 0.02 265);
  --card: oklch(0.985 0.006 260 / 0.82);
  --card-foreground: oklch(0.18 0.02 265);
  --popover: oklch(0.99 0.005 260 / 0.94);
  --popover-foreground: oklch(0.18 0.02 265);
  --primary: oklch(0.55 0.22 265);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.935 0.012 260);
  --secondary-foreground: oklch(0.2 0.02 265);
  --muted: oklch(0.94 0.01 260);
  --muted-foreground: oklch(0.44 0.03 262);
  --accent: oklch(0.92 0.025 268);
  --accent-foreground: oklch(0.18 0.02 265);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.984 0.003 247.858);
  --border: oklch(0.6 0.04 260 / 0.22);
  --input: oklch(0.6 0.04 260 / 0.26);
  --ring: oklch(0.58 0.22 265);
  --glass: oklch(0.985 0.006 260 / 0.78);
  --glass-hover: oklch(1 0 0 / 0.9);
  --glass-border: oklch(0.65 0.06 260 / 0.28);
  --glass-highlight: oklch(1 0 0 / 0.95);
  --brand-blue: oklch(0.58 0.21 248);
  --brand-indigo: oklch(0.54 0.23 275);
  --brand-violet: oklch(0.58 0.22 300);
  --brand-gradient: linear-gradient(
    135deg,
    var(--brand-blue),
    var(--brand-indigo) 58%,
    var(--brand-violet)
  );
  --shadow-glass: 0 16px 42px -12px oklch(0.3 0.08 265 / 0.14), inset 0 1.5px 0 oklch(1 0 0 / 0.9);
  --shadow-glow: 0 8px 28px oklch(0.58 0.22 265 / 0.35), inset 0 1.5px 0 oklch(1 0 0 / 0.7);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.985 0.005 255);
  --sidebar-foreground: oklch(0.18 0.02 265);
  --sidebar-primary: oklch(0.55 0.22 265);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.93 0.015 262);
  --sidebar-accent-foreground: oklch(0.18 0.02 265);
  --sidebar-border: oklch(0.65 0.04 260 / 0.22);
  --sidebar-ring: oklch(0.58 0.22 265);
}

.dark {
  --background: oklch(0.129 0.042 264.695);
  --foreground: oklch(0.984 0.003 247.858);
  --card: oklch(0.208 0.042 265.755);
  --card-foreground: oklch(0.984 0.003 247.858);
  --popover: oklch(0.208 0.042 265.755);
  --popover-foreground: oklch(0.984 0.003 247.858);
  --primary: oklch(0.929 0.013 255.508);
  --primary-foreground: oklch(0.208 0.042 265.755);
  --secondary: oklch(0.279 0.041 260.031);
  --secondary-foreground: oklch(0.984 0.003 247.858);
  --muted: oklch(0.279 0.041 260.031);
  --muted-foreground: oklch(0.704 0.04 256.788);
  --accent: oklch(0.279 0.041 260.031);
  --accent-foreground: oklch(0.984 0.003 247.858);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.984 0.003 247.858);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.551 0.027 264.364);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.208 0.042 265.755);
  --sidebar-foreground: oklch(0.984 0.003 247.858);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.279 0.041 260.031);
  --sidebar-accent-foreground: oklch(0.984 0.003 247.858);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.551 0.027 264.364);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    letter-spacing: 0;
    overflow: hidden;
    overscroll-behavior: none;
    color-scheme: light;
  }

  html,
  body {
    width: 100%;
    height: 100%;
  }

  ::selection {
    background: color-mix(in oklab, var(--brand-blue) 35%, transparent);
  }

  * {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklab, var(--brand-blue) 25%, transparent) transparent;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes message-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes avatar-pulse {
  0%,
  100% {
    box-shadow:
      0 0 20px oklch(0.62 0.2 270 / 0.22),
      inset 0 1px 0 oklch(1 0 0 / 0.3);
  }
  50% {
    box-shadow:
      0 0 30px oklch(0.68 0.2 258 / 0.42),
      inset 0 1px 0 oklch(1 0 0 / 0.4);
  }
}

@utility bg-brand-gradient {
  background-image: var(--brand-gradient);
}

@utility shadow-glass {
  box-shadow: var(--shadow-glass);
}

@utility shadow-glow {
  box-shadow: var(--shadow-glow);
}

@utility animate-message-in {
  animation: message-in 0.3s ease-out both;
}

.ak-shell {
  position: relative;
  isolation: isolate;
  display: flex;
  width: 100%;
  height: 100svh;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse 52% 30% at 50% -4%, rgba(0, 0, 0, 0.045), transparent 65%),
    radial-gradient(ellipse 40% 30% at 88% 80%, oklch(0.93 0.015 280 / 0.06), transparent 65%),
    linear-gradient(180deg, oklch(0.985 0.002 260), oklch(0.965 0.004 260) 55%, oklch(0.952 0.005 260));
}

.ledger-grid {
  display: none;
}

.market-trace {
  pointer-events: none;
  position: absolute;
  right: 3vw;
  bottom: 10vh;
  z-index: -1;
  display: flex;
  height: 9rem;
  width: min(31rem, 38vw);
  align-items: center;
  justify-content: space-between;
  opacity: 0.12;
  mask-image: linear-gradient(90deg, transparent, black 24%, black 76%, transparent);
}

.market-trace::after {
  position: absolute;
  right: 0;
  left: 0;
  height: 1px;
  background: var(--brand-blue);
  content: "";
}

.market-trace i {
  width: 1px;
  background: var(--brand-blue);
  box-shadow: 0 0 10px color-mix(in oklab, var(--brand-blue) 50%, transparent);
}

.market-trace i:nth-child(1),
.market-trace i:nth-child(8) {
  height: 18%;
}
.market-trace i:nth-child(2),
.market-trace i:nth-child(6) {
  height: 42%;
}
.market-trace i:nth-child(3) {
  height: 67%;
}
.market-trace i:nth-child(4),
.market-trace i:nth-child(9) {
  height: 36%;
}
.market-trace i:nth-child(5) {
  height: 82%;
}
.market-trace i:nth-child(7) {
  height: 58%;
}

.intelligence-rail {
  position: relative;
  z-index: 20;
  display: flex;
  width: 15rem;
  height: 100svh;
  flex: 0 0 15rem;
  flex-direction: column;
  border-right: 1px solid color-mix(in oklab, var(--glass-border) 72%, transparent);
  background: color-mix(in oklab, var(--background) 82%, transparent);
  padding: 1.35rem 1rem;
  box-shadow: inset -1px 0 0 oklch(1 0 0 / 0.018);
  backdrop-filter: blur(20px) saturate(120%);
}

.rail-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.15rem 0.15rem 1.75rem;
}

.rail-brand div:last-child,
.rail-foot div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.rail-brand strong {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 600;
}

.rail-brand span,
.rail-foot span {
  color: var(--muted-foreground);
  font-size: 0.64rem;
}

.rail-section-label {
  padding: 0 0.55rem 0.55rem;
  color: color-mix(in oklab, var(--muted-foreground) 75%, transparent);
  font-family: var(--font-display);
  font-size: 0.625rem;
  font-weight: 600;
  text-transform: uppercase;
}

.rail-layers {
  display: grid;
  gap: 0.25rem;
}

.rail-layer {
  display: flex;
  min-height: 2.7rem;
  align-items: center;
  gap: 0.7rem;
  border: 1px solid transparent;
  border-radius: 0.6rem;
  padding: 0 0.65rem;
  color: var(--muted-foreground);
  font-size: 0.76rem;
}

.rail-layer svg {
  width: 0.95rem;
  height: 0.95rem;
}

.rail-layer-active {
  border-color: color-mix(in oklab, var(--brand-blue) 24%, transparent);
  background: color-mix(in oklab, var(--brand-blue) 9%, transparent);
  color: var(--foreground);
  box-shadow: inset 2px 0 0 color-mix(in oklab, var(--brand-blue) 76%, transparent);
}

.rail-ledger {
  display: grid;
  margin: 1.5rem 0.55rem 0;
  gap: 0.55rem;
}

.rail-ledger span {
  display: block;
  height: 1px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--brand-blue) 26%, transparent),
    transparent
  );
}

.rail-ledger span:nth-child(2) {
  width: 72%;
}
.rail-ledger span:nth-child(3) {
  width: 88%;
}
.rail-ledger span:nth-child(4) {
  width: 45%;
}

.rail-foot {
  display: flex;
  margin-top: auto;
  align-items: center;
  gap: 0.65rem;
  border-top: 1px solid var(--glass-border);
  padding: 1rem 0.55rem 0.15rem;
}

.rail-foot > svg {
  width: 1rem;
  height: 1rem;
  color: var(--brand-blue);
}

.rail-foot strong {
  color: var(--foreground);
  font-size: 0.7rem;
  font-weight: 500;
}

.ak-workspace {
  position: relative;
  display: flex;
  min-width: 0;
  height: 100svh;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}

.ak-header {
  position: fixed;
  top: max(1rem, env(safe-area-inset-top));
  left: calc(15rem + (100vw - 15rem) / 2);
  z-index: 30;
  display: flex;
  width: min(calc(100% - 17rem), 58rem);
  transform: translateX(-50%);
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--glass-border);
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--glass) 91%, transparent);
  padding: 0.65rem 0.75rem;
  box-shadow:
    0 12px 34px -8px rgba(0, 0, 0, 0.2),
    0 0 42px -4px rgba(0, 0, 0, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(24px) saturate(145%);
}

.ak-header::before {
  content: "";
  position: absolute;
  inset: -14px -18px;
  z-index: -1;
  border-radius: 1.25rem;
  background: radial-gradient(
    ellipse 85% 75% at 50% 50%,
    rgba(0, 0, 0, 0.08),
    rgba(0, 0, 0, 0.025) 55%,
    transparent 80%
  );
  filter: blur(14px);
  pointer-events: none;
}

/* Premium Black/Dark Glass Buttons Above Chat (Excluding Get Started) */
.ak-header button:not(.glass-btn-send):not(.auth-signup),
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup),
.ak-header .auth-signin {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14) !important;
  background: linear-gradient(
    180deg,
    rgba(24, 24, 30, 0.9),
    rgba(12, 12, 16, 0.95)
  ) !important;
  color: #f8fafc !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.16),
    inset 0 -1px 0 rgba(0, 0, 0, 0.5),
    0 4px 14px -2px rgba(0, 0, 0, 0.45),
    0 0 18px -2px rgba(0, 0, 0, 0.32) !important;
  backdrop-filter: blur(16px) saturate(140%);
  transition:
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 220ms ease,
    border-color 220ms ease,
    background 220ms ease,
    opacity 180ms ease;
}

.ak-header button:not(.glass-btn-send):not(.auth-signup) svg,
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup) svg,
.ak-header .auth-signin svg {
  color: #f1f5f9 !important;
}

.ak-header button:not(.glass-btn-send):not(.auth-signup):hover:not(:disabled),
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup):hover:not(:disabled),
.ak-header .auth-signin:hover:not(:disabled) {
  transform: scale(1.04);
  border-color: rgba(255, 255, 255, 0.26) !important;
  background: linear-gradient(
    180deg,
    rgba(38, 38, 46, 0.95),
    rgba(18, 18, 24, 0.98)
  ) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    inset 0 -1px 0 rgba(0, 0, 0, 0.6),
    0 6px 20px -2px rgba(0, 0, 0, 0.65),
    0 0 24px -2px rgba(0, 0, 0, 0.48) !important;
}

.ak-header button:not(.glass-btn-send):not(.auth-signup):disabled,
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup):disabled {
  opacity: 0.35;
  cursor: not-allowed;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25) !important;
}

/* Restored Get Started Button: Exactly to previous version */
.ak-header .glass-btn-send,
.ak-header .auth-signup {
  border: 1px solid oklch(0.7 0.15 250 / 0.5) !important;
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.3), oklch(1 0 0 / 0) 55%),
    var(--brand-gradient) !important;
  color: var(--primary-foreground) !important;
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.5),
    0 0 20px oklch(0.6 0.22 265 / 0.45),
    0 6px 16px -6px oklch(0.35 0.08 265 / 0.3) !important;
  backdrop-filter: blur(18px) saturate(160%);
  filter: none;
}
.ak-header .glass-btn-send:hover:not(:disabled),
.ak-header .auth-signup:hover:not(:disabled) {
  transform: scale(1.04);
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.4), oklch(1 0 0 / 0) 55%),
    var(--brand-gradient) !important;
  filter: brightness(1.08) !important;
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.6),
    0 0 28px oklch(0.62 0.24 262 / 0.6) !important;
}

/* Button Click / Activation Glow: Soft black/dark/charcoal ambient glow across all buttons EXCEPT Get Started */
button:not(.glass-btn-send):not(.auth-signup):active:not(:disabled),
[role="button"]:not(.glass-btn-send):not(.auth-signup):active:not(:disabled),
.glass-btn:not(.glass-btn-send):not(.auth-signup):active:not(:disabled),
.ak-chip:active:not(:disabled),
.send-button:active:not(:disabled),
.assistant-actions button:active:not(:disabled),
.model-pill:active:not(:disabled),
.ak-header button:not(.glass-btn-send):not(.auth-signup):active:not(:disabled) {
  transform: scale(0.96) !important;
  outline: none !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.16),
    0 0 0 1px rgba(0, 0, 0, 0.18),
    0 0 18px 3px rgba(15, 23, 42, 0.32),
