.ak-composer::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: 0;
  border-radius: 0.95rem;
  padding: 1px;
  background: conic-gradient(
    from var(--ak-angle),
    transparent 0deg,
    oklch(0.72 0.14 220 / 0.55) 40deg,
    oklch(0.64 0.21 260 / 0.7) 80deg,
    oklch(0.6 0.2 290 / 0.5) 120deg,
    transparent 170deg,
    transparent 360deg
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  -webkit-mask-composite: xor;
  opacity: 0.55;
  pointer-events: none;
  animation: ak-border-spin 9s linear infinite;
  transition: opacity 240ms ease;
}
.ak-composer:focus-within::before {
  opacity: 1;
  animation-duration: 5s;
}
.ak-composer > [data-slot="input-group"] {
  position: relative;
  z-index: 1;
  border: 1px solid var(--glass-border);
  border-radius: 0.85rem;
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.05), transparent 40%),
    color-mix(in oklab, var(--glass) 94%, transparent);
  box-shadow:
    var(--shadow-glass),
    inset 0 1px 0 oklch(1 0 0 / 0.08),
    0 0 38px oklch(0.58 0.18 272 / 0.08);
  backdrop-filter: blur(28px) saturate(150%);
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease,
    background 180ms ease;
}
.ak-composer > [data-slot="input-group"]:focus-within {
  border-color: color-mix(in oklab, var(--brand-blue) 40%, var(--glass-border));
  box-shadow:
    var(--shadow-glass),
    inset 0 1px 0 oklch(1 0 0 / 0.1),
    0 0 44px oklch(0.61 0.2 265 / 0.22);
}

/* Apple-style glass controls */
.glass-btn {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid oklch(0.65 0.06 260 / 0.25);
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.8), oklch(1 0 0 / 0.5) 55%),
    linear-gradient(135deg, oklch(0.62 0.18 255 / 0.12), oklch(0.58 0.18 290 / 0.08));
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.9),
    inset 0 -1px 0 oklch(0 0 0 / 0.08),
    0 6px 18px -8px oklch(0.3 0.06 265 / 0.15);
  backdrop-filter: blur(18px) saturate(160%);
  transition:
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 220ms ease,
    border-color 220ms ease,
    background 220ms ease,
    filter 220ms ease;
}
.glass-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: linear-gradient(115deg, transparent 30%, oklch(1 0 0 / 0.5) 50%, transparent 70%);
  transform: translateX(-120%);
