  box-shadow:
    inset 0 1px 0 oklch(1 0 0),
    inset 0 -1px 0 oklch(0 0 0 / 0.08),
    0 0 16px 2px rgba(15, 23, 42, 0.25),
    0 8px 22px -8px rgba(0, 0, 0, 0.2);
}
.glass-btn:hover:not(:disabled)::after {
  transform: translateX(120%);
}
.glass-btn:active:not(:disabled) {
  transform: scale(0.95);
  transition-duration: 90ms;
}
.glass-btn-send {
  border-color: oklch(0.7 0.15 250 / 0.5);
