/* ---- Antigravity Bitcoin field, logo, send, model control ---- */
.bitcoin-field {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}
.btc-coin {
  position: absolute;
  will-change: transform;
}
.btc-dir-fall {
  top: -15vh;
  animation-name: btc-fall;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}
.btc-dir-rise {
  bottom: -15vh;
  animation-name: btc-rise;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}
.btc-spin {
  display: block;
  animation: btc-rotate 6s ease-in-out infinite alternate;
}
.btc-far { opacity: 0.38; filter: blur(1.2px) saturate(0.95); }
.btc-mid { opacity: 0.65; filter: blur(0.3px) drop-shadow(0 4px 12px rgba(0, 0, 0, 0.15)); }
.btc-near {
  opacity: 0.88;
  filter: drop-shadow(0 0 16px rgba(245, 158, 11, 0.35)) drop-shadow(0 8px 18px rgba(0, 0, 0, 0.2));
}
@keyframes btc-fall {
  0% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(32px, 65vh, 0); }
  100% { transform: translate3d(-16px, 130vh, 0); }
}
@keyframes btc-rise {
  0% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(-32px, -65vh, 0); }
  100% { transform: translate3d(16px, -130vh, 0); }
}
@keyframes btc-rotate {
  from { transform: rotateY(-38deg) rotateZ(-16deg); }
  to { transform: rotateY(38deg) rotateZ(16deg); }
}
.ak-mark {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(circle at 35% 25%, oklch(0.72 0.18 245 / 0.4), transparent 65%),
    linear-gradient(145deg, oklch(0.5 0.22 255), oklch(0.42 0.24 275)) !important;
  border: 1px solid oklch(0.75 0.16 245 / 0.45) !important;
  border-radius: 0.62rem;
  box-shadow:
    0 0 0 1px oklch(0.65 0.18 255 / 0.25),
    0 0 24px -2px oklch(0.58 0.22 255 / 0.45),
    0 8px 20px -4px oklch(0.45 0.22 265 / 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.55),
    inset 0 -2px 6px rgba(0, 0, 0, 0.25) !important;
}
.ak-mark::before {
  content: "";
  position: absolute;
  inset: -6px;
  z-index: -1;
  border-radius: 0.85rem;
  background: radial-gradient(
    circle,
    oklch(0.58 0.22 255 / 0.35) 0%,
    oklch(0.5 0.22 275 / 0.12) 55%,
