  border: 1px solid oklch(0.68 0.12 260 / 0.28) !important;
  box-shadow: inset 0 1px 0 oklch(1 0 0 / 0.8), 0 0 12px oklch(0.6 0.2 265 / 0.2) !important;
  transition: transform 0.18s ease, box-shadow 0.25s ease, background 0.25s ease, filter 0.25s ease !important;
}
.send-button.is-ready {
  background: linear-gradient(145deg, oklch(0.6 0.22 250), oklch(0.54 0.24 275)) !important;
  box-shadow: inset 0 1px 0 oklch(1 0 0 / 0.5), 0 0 20px oklch(0.62 0.22 265 / 0.5) !important;
}
.send-button.is-ready:hover { filter: brightness(1.08); transform: scale(1.06); box-shadow: inset 0 1px 0 oklch(1 0 0 / 0.5), 0 0 18px 2px rgba(15, 23, 42, 0.28) !important; }
