}
.animate-float {
  animation: float-hero 4s ease-in-out infinite;
}
.model-pop, [data-slot="popover-content"], [data-slot="dropdown-menu-content"], .glass-dialog {
  background: linear-gradient(180deg, oklch(1 0 0 / 0.94), oklch(0.98 0.005 265 / 0.82) 40%) !important;
  backdrop-filter: blur(24px) saturate(160%);
  border: 1px solid color-mix(in oklab, var(--brand-blue) 30%, oklch(0 0 0 / 0.1)) !important;
  border-radius: 1.1rem !important;
  box-shadow:
    inset 0 1px 0 oklch(1 0 0),
    0 0 0 1px oklch(0.6 0.18 280 / 0.1),
    0 0 40px -12px oklch(0.6 0.2 275 / 0.35),
    0 24px 50px -16px oklch(0.3 0.06 265 / 0.2) !important;
  color: var(--foreground) !important;
}
.model-pop[data-state="open"], .glass-dialog[data-state="open"] { animation: pop-in 0.26s cubic-bezier(0.2, 0.9, 0.3, 1) both; }
.model-pop[data-state="closed"], .glass-dialog[data-state="closed"] { animation: pop-out 0.16s ease-in both; }
@keyframes pop-in {
  from { opacity: 0; scale: 0.96; translate: 0 8px; }
  to { opacity: 1; scale: 1; translate: 0 0; }
}
@keyframes pop-out { to { opacity: 0; scale: 0.97; } }
.pref-seg {
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 0.7rem;
  background: oklch(0 0 0 / 0.06);
  border: 1px solid oklch(0 0 0 / 0.08);
}
.pref-opt {
  flex: 1;
  padding: 0.3rem 0.4rem;
  border-radius: 0.5rem;
  font-size: 12px;
  color: var(--muted-foreground);
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
}
.pref-opt:hover { color: var(--foreground); }
.pref-opt-on {
  color: var(--foreground);
  background: oklch(1 0 0);
  box-shadow: inset 0 1px 0 oklch(1 0 0), 0 2px 8px -2px oklch(0.4 0.12 265 / 0.3);
}
.pref-opt:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }

/* ==========================================================================
   Apple VisionOS Glassmorphism & Interactive Button Utilities
   ========================================================================== */

/* Glass Button Base */
.glass-btn-base {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  isolation: isolate;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: #f1f5f9;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 4px 16px 0 rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
              border-color 200ms ease,
              box-shadow 200ms ease,
              background 200ms ease;
  cursor: pointer;
  user-select: none;
}

.glass-btn-base:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: rgba(255, 255, 255, 0.8) !important;
  background: rgba(255, 255, 255, 0.16);
  box-shadow: 0 8px 24px -4px rgba(255, 255, 255, 0.15),
              0 0 16px rgba(56, 189, 248, 0.16),
              inset 0 1px 1px rgba(255, 255, 255, 0.4);
}

.glass-btn-base:active:not(:disabled) {
  transform: scale(0.97) !important;
}

/* Glass Effect applied to Top Header Action Buttons (except Sign In & Get Started) */
.ak-header button:not(.glass-btn-send):not(.auth-signup):not(.auth-signin),
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup):not(.auth-signin) {
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}
.ak-header button:not(.glass-btn-send):not(.auth-signup):not(.auth-signin):hover:not(:disabled),
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup):not(.auth-signin):hover:not(:disabled) {
  transform: translateY(-2px) !important;
  border-color: rgba(255, 255, 255, 0.8) !important;
  box-shadow: 0 6px 20px -2px rgba(0, 0, 0, 0.5), 0 0 16px rgba(255, 255, 255, 0.2) !important;
}
.ak-header button:not(.glass-btn-send):not(.auth-signup):not(.auth-signin):active:not(:disabled),
.ak-header .glass-btn:not(.glass-btn-send):not(.auth-signup):not(.auth-signin):active:not(:disabled) {
  transform: scale(0.97) !important;
}

/* Glass Effect applied to Input Bar Quick Prompt/Category Buttons (BTC, ETH, etc.) */
.shortcut-btn {
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}
.shortcut-btn:hover:not(:disabled) {
  transform: translateY(-2px) !important;
  border-color: rgba(255, 255, 255, 0.8) !important;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4), 0 0 14px rgba(255, 255, 255, 0.16) !important;
}
.shortcut-btn:active:not(:disabled) {
  transform: scale(0.97) !important;
}

/* Glass effect for Sidebar secondary nav buttons */
.rail-btn-secondary {
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}
.rail-btn-secondary:hover:not(:disabled) {
  transform: translateY(-2px) !important;
  border-color: rgba(255, 255, 255, 0.8) !important;
}
.rail-btn-secondary:active:not(:disabled) {
  transform: scale(0.97) !important;
}

/* Contextual One-Click Follow-Up Prompt Pills */
.followup-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.32rem 0.75rem;
  border-radius: 9999px;
  font-size: 11.5px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  cursor: pointer;
  transition: all 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
  white-space: nowrap;
}
.followup-pill:hover:not(:disabled) {
  transform: translateY(-1.5px);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.65);
  background: rgba(255, 255, 255, 0.12);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25), 0 0 12px rgba(56, 189, 248, 0.15);
}
.followup-pill:active:not(:disabled) {
  transform: scale(0.97);
}

/* Marquee Ticker Continuous Scrolling (Right -> Left Infinite Loop) */
.ticker-scroll-wrapper {
  mask-image: linear-gradient(90deg, transparent, #000 2rem, #000 calc(100% - 2rem), transparent);
}
.ticker-marquee, .ticker-marquee-track, .animate-marquee {
  display: inline-flex;
  width: max-content;
  animation: ticker-scroll 32s linear infinite;
}
.ticker-marquee:hover, .ticker-marquee-track:hover, .animate-marquee:hover {
  animation-play-state: paused;
}
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Voice Visualizer Wave Bars */
.voice-wave-bar {
  animation: voice-wave-bounce 0.8s ease-in-out infinite;
}
@keyframes voice-wave-bounce {
  0%, 100% { height: 6px; }
  50% { height: 18px; }
}

@keyframes border-light-travel {
  0% {
    border-color: rgba(255, 255, 255, 0.95);
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0), var(--shadow-glass);
  }
  35% {
    border-color: oklch(0.62 0.24 250);
    box-shadow: 0 0 25px 3px oklch(0.6 0.22 255 / 0.45), inset 0 0 12px oklch(0.65 0.2 240 / 0.35);
  }
  100% {
    border-color: rgba(255, 255, 255, 0.95);
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0), var(--shadow-glass);
  }
}
.composer-glow-active {
  animation: border-light-travel 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes chat-box-breathe {
  0%, 100% {
    opacity: 0.35;
    transform: scale(1);
  }
  50% {
    opacity: 0.7;
    transform: scale(1.01);
  }
}
.chat-box-halo {
  animation: chat-box-breathe 4s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .model-pop, .glass-dialog, .ak-shell::before, .ticker-marquee, .voice-wave-bar { animation: none !important; }
}

